from collections import deque
class Deque:
    def __init__(self):
        self.deque = deque()
    def add_front(self, item):
        self.deque.appendleft(item)
    def add_back(self, item):
        self.deque.append(item)
    def remove_front(self):
        return self.deque.popleft()

