import threading
class MultiQueue:
    def __init__(self, num_queues):
        self.lock = threading.Lock()
        self.queues = [[] for _ in range(num_queues)]
    def enqueue(self, queue_index, item):
        with self.lock:
            self.queues[queue_index].append(item)
    def dequeue(self, queue_index):
        with self.lock:
            return self.queues[queue_index].pop(0) if self.queues[queue_index] else None
